css:
@font-face {
    font-family: 'TWKEverett';
    font-style: normal;
    font-weight: normal;
    src: url('/assets/mvd/font/TWKEverett_Regular_web.woff');
}
@font-face {
    font-family: 'TWKEverettBold';
    font-style: normal;
    font-weight: bold;
    src: url('/assets/mvd/font/TWKEverett_Bold_web.woff');
}
#logo_kopfzeile { width: 40mm; min-height: 25mm; margin-left: 15mm; padding-top: 14.5mm !important; }
.print-format {
    margin-top: 0mm;
    margin-bottom: 10mm;
    margin-left: 0mm;
    margin-right: 0mm;
    font-size: 10pt;
}
.kgs { font-size: 10pt; line-height: 1.35; font-family: 'TWKEverett'; margin-left: 30mm; width: 154mm; max-width: 154mm; }
.kgs table td { font-size: 10pt; }
.kgs-adresse { margin-top: 8mm; }
.kgs-datum { margin-top: 8mm; }
.kgs h1 { font-size: 14pt; margin-top: 5mm; margin-bottom: 2mm; }
.kgs-daten { width: 100%; margin: 2mm 0; }
.kgs-daten td { padding: 0.5mm 2mm; vertical-align: top; }
.kgs-daten td:first-child { width: 55mm; color: #666; }
.kgs-block, .kgs p.kgs-block { margin-top: 3mm; margin-bottom: 0; }
.kgs ul { margin-bottom: 0; }
.kgs-unterschrift { width: 100%; margin-top: 15mm; }
.kgs-abschluss { page-break-inside: avoid; }
.kgs-unterschrift td { border-top: 1px solid #000; padding-top: 1mm; width: 45%; }
.kgs-unterschrift td:nth-child(2) { border-top: 0; width: 10%; }
.kgs-text { margin: 1mm 0 0 0; }
.kgs-checkbox { margin-top: 5mm; }
.kgs-kaestchen { display: inline-block; width: 3.5mm; height: 3.5mm; border: 1px solid #000; margin-right: 2mm; vertical-align: -0.5mm; }
